import { execFileSync } from 'node:child_process'
import { chmodSync, mkdirSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'

/**
 * Test videos generated by ffmpeg (Story 11.3, architecture "Tests": no binary committed).
 * `testsrc` pattern, 320×180 at 10 fps, native `mpeg4` encoder (no libx264 dependency):
 * a few kilobytes, generated in well under a second.
 */
const DIR = join(tmpdir(), 'anta-test-videos')

function ffmpeg(name: string, args: string[]): string {
  mkdirSync(DIR, { recursive: true })
  const path = join(DIR, name)
  execFileSync('ffmpeg', ['-nostdin', '-hide_banner', '-loglevel', 'error', '-y', ...args, path], {
    timeout: 20_000,
  })
  return path
}

export function makeMp4(name: string, seconds: number): string {
  return ffmpeg(name, [
    '-f',
    'lavfi',
    '-i',
    `testsrc=size=320x180:rate=10:duration=${seconds}`,
    '-c:v',
    'mpeg4',
    '-pix_fmt',
    'yuv420p',
  ])
}

/**
 * Red until t = 1 s, blue from t = 1 s (review of 11.3): tells the frame at t = 1 s from the
 * t = 0 fallback.
 */
export function makeColorSwitchMp4(name: string, seconds = 2): string {
  return ffmpeg(name, [
    '-f',
    'lavfi',
    '-i',
    `color=c=red:size=320x180:rate=10:duration=${seconds},drawbox=c=blue:t=fill:enable='gte(t,1)'`,
    '-c:v',
    'mpeg4',
    '-pix_fmt',
    'yuv420p',
  ])
}

/** MP4 container with an audio track only (no frame to extract). */
export function makeAudioOnlyMp4(name: string): string {
  return ffmpeg(name, ['-f', 'lavfi', '-i', 'sine=frequency=440:duration=1', '-c:a', 'aac'])
}

/** Fake ffmpeg that never ends: exercises the real timeout path (`SIGKILL`). */
export function makeSleepingBinary(name: string): string {
  mkdirSync(DIR, { recursive: true })
  const path = join(DIR, name)
  writeFileSync(path, '#!/bin/sh\nexec sleep 30\n')
  chmodSync(path, 0o755)
  return path
}

/**
 * A file detected as `video/mp4` by its magic bytes (`ftyp` box) but whose content is not a
 * decodable video: the upload is accepted, the frame extraction fails.
 */
export function makeCorruptMp4(name: string): string {
  mkdirSync(DIR, { recursive: true })
  const path = join(DIR, name)
  const ftyp = Buffer.from([
    0x00, 0x00, 0x00, 0x18, 0x66, 0x74, 0x79, 0x70, 0x69, 0x73, 0x6f, 0x6d, 0x00, 0x00, 0x02, 0x00,
    0x69, 0x73, 0x6f, 0x6d, 0x6d, 0x70, 0x34, 0x31,
  ])
  writeFileSync(path, Buffer.concat([ftyp, Buffer.alloc(4096, 0x5a)]))
  return path
}
